1	#!/usr/bin/env node
2	// Generates src/generated/registry.mjs from registry/*.csv.
3	//   node tools/codegen.mjs            write it
4	//   node tools/codegen.mjs --verify   fail if it is out of date
5	//   node tools/codegen.mjs --root DIR work on another checkout
6	import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
7	import { dirname, join } from "node:path";
8	import { fileURLToPath } from "node:url";
9	
10	const args = process.argv.slice(2);
11	const at = args.indexOf("--root");
12	const root = at >= 0 ? args[at + 1] : join(dirname(fileURLToPath(import.meta.url)), "..");
13	const OUT = "src/generated/registry.mjs";
14	
15	function parse(text) {
16	  const lines = text.split(/\r?\n/).filter((l) => l.trim() !== "");
17	  const header = lines[0].split(",").map((h) => h.trim());
18	  const rows = {};
19	  for (const line of lines.slice(1)) {
20	    const cells = line.split(",").map((c) => c.trim());
21	    const rec = {};
22	    header.forEach((h, i) => {
23	      const v = cells[i] ?? "";
24	      if (h !== "code") rec[h] = /^[0-9]+$/.test(v) ? Number(v) : v;
25	    });
26	    rows[cells[0].toUpperCase()] = rec;
27	  }
28	  return rows;
29	}
30	
31	function render() {
32	  const dir = join(root, "registry");
33	  const files = readdirSync(dir).filter((f) => f.endsWith(".csv")).sort();
34	  const out = ["// Generated by tools/codegen.mjs from registry/*.csv. Do not edit by hand.", "",
35	    "export const TABLES = Object.freeze({"];
36	  for (const f of files) {
37	    const rows = parse(readFileSync(join(dir, f), "utf8"));
38	    out.push(`  ${JSON.stringify(f.slice(0, -4))}: Object.freeze({`);
39	    for (const code of Object.keys(rows).sort()) {
40	      const rec = rows[code];
41	      const fields = Object.keys(rec).sort().map((k) => `${JSON.stringify(k)}: ${JSON.stringify(rec[k])}`).join(", ");
42	      out.push(`    ${JSON.stringify(code)}: Object.freeze({ ${fields} }),`);
43	    }
44	    out.push("  }),");
45	  }
46	  out.push("});", "");
47	  return out.join("\n");
48	}
49	
50	const text = render();
51	const target = join(root, OUT);
52	if (args.includes("--verify")) {
53	  if (!existsSync(target) || readFileSync(target, "utf8") !== text) {
54	    console.error(`error: ${OUT} is out of date with registry/*.csv, run npm run codegen`);
55	    process.exit(1);
56	  }
57	} else {
58	  writeFileSync(target, text);
59	  console.log(`wrote ${OUT}`);
60	}
61

